    { customer:'West & Wren', type:'Boutique clothing shop', product:'Loyalty cards', desc:'A handsome card for customers who keep coming back.', icon:'◇', avatar:'avatar-blue', qty:220, size:'Business card · 2-sided', paper:'Everyday', deadline:4, reward:580, cost:48, ink:31, quality:73, finish:'Cut & package', patience:'Particular', customerLine:'A local boutique is launching a customer club.' },
    { customer:'Harbor Hotel', type:'Local hospitality group', product:'Guest welcome booklets', desc:'A polished welcome pack for travelers arriving in town.', icon:'⌂', avatar:'avatar-green', qty:300, size:'A5 · booklet', paper:'Everyday', deadline:5, reward:850, cost:75, ink:49, quality:78, finish:'Fold & bind', patience:'Particular', customerLine:'The new hotel wants guests to feel at home.' },
    { customer:'City Arts Council', type:'Citywide organization', product:'Open studio brochures', desc:'A beautiful guide to the city’s independent artists.', icon:'✳', avatar:'avatar-yellow', qty:500, size:'A4 · folded', paper:'Everyday', deadline:5, reward:1250, cost:122, ink:72, quality:82, finish:'Fold & package', patience:'Particular', customerLine:'The annual citywide arts weekend is taking shape.' },
  ];
  const upgrades = [
    { id:'paper', icon:'▤', color:'green', name:'A little more breathing room', desc:'Add a compact paper rack and dedicated stock space.', effect:'+160 sheets of storage', cost:145, requires:0, apply:s=>{s.maxPaper+=160;s.paper+=160;} },
    { id:'ink', icon:'◉', color:'orange', name:'Color that lasts', desc:'A better cartridge gives your prints a richer, cleaner finish.', effect:'+8% print quality · +40% ink', cost:210, requires:1, apply:s=>{s.quality+=8;s.ink=Math.min(100,s.ink+40);} },
    { id:'machine', icon:'▣', color:'blue', name:'A printer with promise', desc:'Trade up to a dependable mid-range machine for faster runs.', effect:'+18% quality · +10 sheets / minute', cost:380, requires:2, apply:s=>{s.quality+=18;s.machine='QuickPrint 240';s.speed=22;s.condition=Math.min(100,s.condition+12);} },
    { id:'finishing', icon:'✂', color:'purple', name:'Neat edges, every time', desc:'A sturdy finishing station for trimming, folding, and packaging.', effect:'+15% finishing quality', cost:330, requires:3, apply:s=>{s.quality+=15;s.finishing=true;} },
    { id:'studio', icon:'⌂', color:'orange', name:'A studio of your own', desc:'Move from the starter room into a brighter, roomier workshop.', effect:'Bigger orders · +250 sheets storage', cost:640, requires:4, apply:s=>{s.maxPaper+=250;s.paper+=180;s.studio=true;} },
    { id:'industrial', icon:'⚙', color:'green', name:'The production floor', desc:'Your first industrial press: bulk runs become an exciting possibility.', effect:'+35% quality · +40 sheets / minute', cost:1150, requires:6, apply:s=>{s.quality+=35;s.machine='Pressmaster X1';s.speed=52;s.industrial=true;s.condition=100;} },
  ];
  const freshState = () => ({ cash:420, day:1, reputation:12, done:0, paper:120, maxPaper:120, ink:80, quality:42, condition:86, machine:'Old Reliable', speed:12, revenue:0, spent:0, active:[], completed:[], available:['job-1','job-2'], unlocked:2, upgrades:[], generated:0, sound:true });
  let state;
  try { state=JSON.parse(localStorage.getItem(SAVE_KEY)) || freshState(); } catch { state=freshState(); }
  const $ = (sel, root=document) => root.querySelector(sel);
  const $$ = (sel, root=document) => [...root.querySelectorAll(sel)];
  const money = n => '$'+Math.floor(n).toLocaleString('en-US');
  const orderById = id => { const m=id.match(/^job-(\d+)$/); return m ? orderTemplates[Number(m[1])-1] : null; };
  const save = () => { try { localStorage.setItem(SAVE_KEY,JSON.stringify(state)); } catch {} };
  let toastTimer;
  function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2500);}
  function updateNav(){
    $('#cashValue').textContent=money(state.cash);$('#cashDelta').textContent=money(Math.max(0,state.revenue));$('#repValue').textContent=state.reputation;$('#repMeter').style.width=state.reputation+'%';$('#doneValue').textContent=state.done;$('#stockValue').textContent=state.paper;$('#inkStock').textContent='Ink: '+state.ink+'%';$('#paperCount').textContent=state.paper;$('#inkCount').textContent=state.ink;$('#paperBar').style.width=Math.min(100,state.paper/state.maxPaper*100)+'%';$('#inkBar').style.width=state.ink+'%';$('#conditionText').textContent=(state.condition>65?'Good':state.condition>35?'Fair':'Needs care')+' · '+state.condition+'%';$('#conditionBar').style.width=state.condition+'%';$('#shopLevel').textContent=state.industrial?'Citywide printworks':state.studio?'Growing studio':state.done>=3?'Neighborhood print shop':'Starter studio';
    ['#sideDay','#topDay','#welcomeDay'].forEach(sel=>$(sel).textContent=state.day);
    $('#navOrderCount').textContent=state.available.length+state.active.length;
    $('#activeCount').textContent=state.active.length+' active';
    $('#activeTabCount').textContent=state.active.length;$('#completedTabCount').textContent=state.completed.length;$('#availableTabCount').textContent=state.available.length;$('#ordersAvailable').textContent=state.available.length;
    const progress=Math.min(100,state.done*100);$('#milestoneProgress').style.width=progress+'%';$('#milestoneLabel').textContent=Math.min(state.done,1)+' of 1 orders completed';
    $('#ledgerRevenue').textContent='+'+money(state.revenue);$('#ledgerSpent').textContent='−'+money(state.spent);$('#ledgerCash').textContent=money(state.cash);
    const goal=state.done<3?3:state.done<7?7:state.done<12?12:20;$('#nextGoal').textContent='Complete '+goal+' orders';$('#goalTrack').style.width=Math.min(100,state.done/goal*100)+'%';$('#goalLabel').textContent=Math.min(state.done,goal)+' / '+goal+' completed';$('#growthStage').innerHTML=(state.industrial?'Citywide printworks':state.studio?'Growing studio':state.done>=3?'Neighborhood shop':'Neighborhood shop')+' <i>'+String(state.industrial?4:state.studio?3:state.done>=3?2:1).padStart(2,'0')+'</i>';
    renderActive();renderOrders();renderUpgrades();save();
  }
  function renderActive(){const root=$('#activeOrders');if(!state.active.length){root.innerHTML='<div class="active-empty"><span>✦</span><div><b>A clear desk is a good place to start.</b>Pick up an order and let the printer warm up.</div></div>';return;}root.innerHTML=state.active.map(id=>{const o=orderById(id);if(!o)return'';return `<div class="active-order"><div class="product-icon">${o.icon}</div><div class="active-order-copy"><b>${o.product}</b><small>${o.qty} copies · Due in ${Math.max(1,o.deadline-(state.day-(state.acceptedAt?.[id]||state.day)))} day(s)</small></div><button data-produce="${id}">Print order →</button></div>`}).join('');}
  function renderOrders(){const filter=$('.order-tab.active')?.dataset.filter||'available';let ids=filter==='available'?state.available:filter==='active'?state.active:state.completed;const root=$('#orderGrid');$('#orderEmpty').classList.toggle('hidden',ids.length>0);root.classList.toggle('hidden',ids.length===0);
    root.innerHTML=ids.map(id=>{const o=orderById(id);if(!o)return'';if(filter==='available')return `<article class="order-card"><div class="order-card-top"><div style="display:flex;align-items:center;gap:10px"><div class="customer-avatar ${o.avatar}">${o.icon}</div><div><div class="customer-name">${o.customer}</div><div class="customer-type">${o.type}</div></div></div><span class="deadline ${o.deadline>=3?'easy':''}">◷ ${o.deadline} day${o.deadline===1?'':'s'} left</span></div><h3 class="order-title">${o.product}</h3><p class="order-desc">${o.desc}</p><div class="order-details"><div class="detail-cell"><span>QUANTITY</span><b>${o.qty} copies</b></div><div class="detail-cell"><span>SIZE</span><b>${o.size}</b></div><div class="detail-cell"><span>FINISH</span><b>${o.finish}</b></div></div><div class="order-requirements"><span class="requirement">✳ ${o.quality}% quality</span><span class="requirement">▧ ${o.paper} paper</span><span class="requirement">◷ ${o.patience}</span></div><div class="order-card-bottom"><div class="reward"><b>${money(o.reward)}</b><small>payment</small></div><button class="accept-button" data-accept="${id}" ${state.paper<o.qty||state.ink<o.ink?'disabled':''}>${state.paper<o.qty||state.ink<o.ink?'Restock first':'Accept order →'}</button></div></article>`;
      if(filter==='active')return `<article class="order-card active-card"><div class="order-card-top"><div style="display:flex;align-items:center;gap:10px"><div class="customer-avatar ${o.avatar}">${o.icon}</div><div><div class="customer-name">${o.customer}</div><div class="customer-type">${o.type}</div></div></div><span class="order-status">● IN PRODUCTION</span></div><h3 class="order-title">${o.product}</h3><p class="order-desc">${o.customerLine}</p><div class="order-details"><div class="detail-cell"><span>QUANTITY</span><b>${o.qty} copies</b></div><div class="detail-cell"><span>PRINT QUALITY</span><b>${o.quality}% requested</b></div><div class="detail-cell"><span>YOUR MACHINE</span><b>${state.machine}</b></div></div><div class="production-step"><b>Ready to make something good?</b><p>This run uses ${o.qty} sheets and ${o.ink}% ink. Required finish: ${o.finish.toLowerCase()}.</p></div><label class="quality-control">Print attention <select data-quality="${id}"><option value="careful">Careful finish · +quality, more ink</option><option value="balanced" selected>Steady hands · balanced</option><option value="quick">Quick run · save time</option></select></label><div class="order-card-bottom"><div class="reward"><b>${money(o.reward)}</b><small>on delivery</small></div><button class="produce-button" data-produce="${id}">Run the print job →</button></div></article>`;
      return `<article class="order-card completed-card"><div class="order-card-top"><div style="display:flex;align-items:center;gap:10px"><div class="customer-avatar ${o.avatar}">${o.icon}</div><div><div class="customer-name">${o.customer}</div><div class="customer-type">${o.type}</div></div></div><span class="completed-stamp">✓ DELIVERED</span></div><h3 class="order-title">${o.product}</h3><p class="order-desc">${o.qty} copies · ${o.finish}</p><div class="order-details"><div class="detail-cell"><span>PAYMENT</span><b>${money(o.reward)}</b></div><div class="detail-cell"><span>QUALITY</span><b>${o.lastQuality||'Good'} finish</b></div><div class="detail-cell"><span>REPUTATION</span><b>+${o.repGain||4} points</b></div></div><div class="production-step"><b>Made with care ✳</b><p>Your work is out in the neighborhood. A little more of your story is being told.</p></div></article>`;
    }).join('');
    $('#waitDay').classList.toggle('hidden',state.available.length>0);
  }
  function renderUpgrades(){const root=$('#upgradeGrid');root.innerHTML=upgrades.map(u=>{const purchased=state.upgrades.includes(u.id);const locked=state.done<u.requires;return `<article class="upgrade-card ${purchased?'purchased':''}"><div class="upgrade-icon ${u.color}">${purchased?'✓':u.icon}</div><div class="upgrade-copy"><h3>${u.name}</h3><p>${u.desc}</p><span class="upgrade-effect">${purchased?'Installed and ready':u.effect}</span></div><button class="upgrade-buy" data-upgrade="${u.id}" ${purchased||locked||state.cash<u.cost?'disabled':''}>${purchased?'Installed':locked?`After ${u.requires} orders`:money(u.cost)+' · Invest'}</button></article>`}).join('');}
  function navigate(view){$$('.view').forEach(el=>el.classList.remove('active'));$('#'+view+'View').classList.add('active');$$('.nav-link').forEach(el=>el.classList.toggle('active',el.dataset.view===view));const name={dashboard:'Overview',orders:'Order book',workshop:'Workshop',growth:'Growth & upgrades'}[view];$('#viewCrumb').textContent=name;window.scrollTo({top:0,behavior:'smooth'});}
  document.addEventListener('click',e=>{const nav=e.target.closest('[data-view]');if(nav){navigate(nav.dataset.view);return;}const go=e.target.closest('[data-goto]');if(go){navigate(go.dataset.goto);return;}const accept=e.target.closest('[data-accept]');if(accept){const id=accept.dataset.accept,o=orderById(id);if(!o||state.paper<o.qty||state.ink<o.ink)return;state.available=state.available.filter(x=>x!==id);state.active.push(id);state.acceptedAt=state.acceptedAt||{};state.acceptedAt[id]=state.day;toast(o.customer+' is counting on you. Let’s make it great.');updateNav();return;}const produce=e.target.closest('[data-produce]');if(produce){const id=produce.dataset.produce,o=orderById(id);if(!o)return;const qualityMode=$(`[data-quality="${id}"]`)?.value||'balanced';if(state.paper<o.qty||state.ink<o.ink){toast('You need more paper or ink before this run.');navigate('workshop');return;}state.paper-=o.qty;state.ink-=o.ink+(qualityMode==='careful'?3:0);state.condition=Math.max(15,state.condition-2);const quality=state.quality+(qualityMode==='careful'?12:qualityMode==='quick'?-5:4)+(state.finishing?5:0);let repGain=quality>=o.quality?5:quality>=o.quality-12?3:1;const deadline=state.acceptedAt?.[id]||state.day;const late=state.day-deadline>o.deadline;if(late)repGain=Math.max(0,repGain-2);const pay=Math.max(Math.floor(o.reward*.55),o.reward-(quality<o.quality?Math.floor(o.reward*.12):0)-(late?Math.floor(o.reward*.2):0));state.cash+=pay;state.revenue+=pay;state.done++;state.reputation=Math.min(100,state.reputation+repGain);state.active=state.active.filter(x=>x!==id);state.completed.unshift(id);o.lastQuality=quality>=o.quality?'Lovely':quality>=o.quality-12?'Good':'Needs a little practice';o.repGain=repGain;delete state.acceptedAt?.[id];if(state.done===1){state.unlocked=Math.max(state.unlocked,4);state.available.push('job-3','job-4');}else if(state.done===3){state.unlocked=Math.max(state.unlocked,6);state.available.push('job-5','job-6');}else if(state.done===5){state.unlocked=Math.max(state.unlocked,8);state.available.push('job-7','job-8');}else if(state.done===7){state.unlocked=Math.max(state.unlocked,10);state.available.push('job-9','job-10');}else if(state.done===10){state.unlocked=11;state.available.push('job-11');}const compliment=quality>=o.quality?'The customer loved the finish!':'The job is done—your print skills will grow.';toast(compliment+' +'+repGain+' reputation, '+money(pay)+'.');updateNav();return;}const upgrade=e.target.closest('[data-upgrade]');if(upgrade){const u=upgrades.find(x=>x.id===upgrade.dataset.upgrade);if(!u||state.upgrades.includes(u.id)||state.cash<u.cost||state.done<u.requires)return;state.cash-=u.cost;state.spent+=u.cost;state.upgrades.push(u.id);u.apply(state);toast(u.name+' — a lovely investment.');updateNav();return;}
    const tab=e.target.closest('[data-filter]');if(tab){$$('.order-tab').forEach(x=>x.classList.toggle('active',x===tab));renderOrders();return;}
  });
  $('#buyPaper').addEventListener('click',()=>{if(state.cash<35){toast('Not quite enough cash for paper yet.');return;}state.cash-=35;state.spent+=35;state.paper=Math.min(state.maxPaper,state.paper+100);toast('100 fresh sheets added to the stock room.');updateNav();});
  $('#buyInk').addEventListener('click',()=>{if(state.cash<55){toast('Not quite enough cash for an ink cartridge yet.');return;}state.cash-=55;state.spent+=55;state.ink=Math.min(100,state.ink+65);toast('Fresh ink — rich colors ahead.');updateNav();});
  $('#waitDay').addEventListener('click',()=>{state.day++;if(state.done<state.unlocked&&state.available.length<3){const next=Math.min(orderTemplates.length,state.available.length+state.active.length+state.completed.length+1);const id='job-'+next;if(orderById(id)&&!state.available.includes(id)&&!state.active.includes(id)&&!state.completed.includes(id))state.available.push(id);}if(state.day%4===0&&state.active.length){state.reputation=Math.max(0,state.reputation-1);toast('A customer is waiting. Deliver active jobs soon to keep your promise.');}else toast('A new day, and fresh possibilities.');updateNav();});
  $$('.nav-link').forEach(x=>x.addEventListener('click',()=>navigate(x.dataset.view)));
  $$('.order-tab').forEach(x=>x.addEventListener('click',()=>{$$('.order-tab').forEach(t=>t.classList.toggle('active',t===x));renderOrders();}));
  $('#storyBtn').addEventListener('click',()=>$('#modalBackdrop').classList.remove('hidden'));$('#modalClose').addEventListener('click',()=>$('#modalBackdrop').classList.add('hidden'));$('#modalOkay').addEventListener('click',()=>$('#modalBackdrop').classList.add('hidden'));$('#modalBackdrop').addEventListener('click',e=>{if(e.target.id==='modalBackdrop')e.currentTarget.classList.add('hidden');});
  $('#resetBtn').addEventListener('click',()=>{if(confirm('Start a new shop from the beginning? Your saved progress will be cleared.')){state=freshState();updateNav();navigate('dashboard');toast('A fresh start. Your grandfather would be proud.');}});
  $('#soundBtn').addEventListener('click',e=>{state.sound=!state.sound;e.currentTarget.textContent=state.sound?'♫':'♪';toast(state.sound?'Shop sounds on.':'Shop sounds off.');save();});
  $('#soundBtn').textContent=state.sound?'♫':'♪';
  updateNav();
})();

